fn solve(n: i8) -> i8 {
    // If the perimeter is odd, no valid rectangles.
    if n % 2 != 0 {
        return 0;
    }
    // Now n is even. Two cases based on n mod 4.
    if n % 4 == 2 {
        // n/4 integer division yields the correct count for n ≡ 2 (mod 4).
        n / 4
    } else {
        // n is divisible by 4: subtract 1 to exclude the square.
        n / 4 - 1
    }
}

